// Build cache: a layer's key = parent key + instruction + its inputs.
function build(cache, steps) {
  let key = "", misses = 0;
  for (const [cmd, inp] of steps) {
    key = key + "/" + cmd + ":" + inp; // parent key is part of the key
    let state;
    if (cache.has(key)) state = "HIT ";
    else { cache.add(key); state = "MISS"; misses++; }
    console.log("  " + state + " " + cmd + " " + inp);
  }
  return misses;
}
// manifest first, source last
const good = v => [["FROM", "node20"], ["RUN", "apt-get"], ["COPY", "package.json"],
  ["RUN", "npm-ci"], ["COPY", "src-" + v]];
// everything copied before install
const bad = v => [["FROM", "node20"], ["RUN", "apt-get"], ["COPY", "all-" + v],
  ["RUN", "npm-ci"]];

for (const [name, layout] of [["good order", good], ["bad order", bad]]) {
  const cache = new Set();
  console.log(name + ": first build");
  build(cache, layout("v1"));
  console.log(name + ": after editing source");
  const n = build(cache, layout("v2"));
  console.log("rebuilt layers: " + n);
}

