#include <bits/stdc++.h>
using namespace std;
typedef vector<pair<string, string>> Steps;

// Build cache: a layer's key = parent key + instruction + its inputs.
int build(set<string>& cache, const Steps& steps) {
    string key;
    int misses = 0;
    for (auto& s : steps) {
        key = key + "/" + s.first + ":" + s.second; // parent key is part of the key
        string state;
        if (cache.count(key)) state = "HIT ";
        else { cache.insert(key); state = "MISS"; misses++; }
        cout << "  " << state << " " << s.first << " " << s.second << "\n";
    }
    return misses;
}

// manifest first, source last
Steps good(string v) {
    return {{"FROM", "node20"}, {"RUN", "apt-get"}, {"COPY", "package.json"},
            {"RUN", "npm-ci"}, {"COPY", "src-" + v}};
}
// everything copied before install
Steps bad(string v) {
    return {{"FROM", "node20"}, {"RUN", "apt-get"}, {"COPY", "all-" + v}, {"RUN", "npm-ci"}};
}

int main() {
    for (int i = 0; i < 2; i++) {
        string name = i == 0 ? "good order" : "bad order";
        set<string> cache;
        cout << name << ": first build\n";
        build(cache, i == 0 ? good("v1") : bad("v1"));
        cout << name << ": after editing source\n";
        int n = build(cache, i == 0 ? good("v2") : bad("v2"));
        cout << "rebuilt layers: " << n << "\n";
    }
}

