    static int Build(HashSet<string> cache, string[][] steps)
    {
        string key = "";
        int misses = 0;
        foreach (string[] s in steps)
        {
            key = key + "/" + s[0] + ":" + s[1]; // parent key is part of the key
            string state;
            if (cache.Contains(key)) state = "HIT ";
            else { cache.Add(key); state = "MISS"; misses++; }
            Console.WriteLine("  " + state + " " + s[0] + " " + s[1]);
        }
        return misses;
    }

    // manifest first, source last
    static string[][] Good(string v)
    {
        return new string[][] { new[] {"FROM", "node20"}, new[] {"RUN", "apt-get"},
            new[] {"COPY", "package.json"}, new[] {"RUN", "npm-ci"}, new[] {"COPY", "src-" + v} };
    }

    // everything copied before install
    static string[][] Bad(string v)
    {
        return new string[][] { new[] {"FROM", "node20"}, new[] {"RUN", "apt-get"},
            new[] {"COPY", "all-" + v}, new[] {"RUN", "npm-ci"} };
    }

